// src/App.js
import React, { useState } from 'react';
import axios from 'axios';
import CodeEditor from './components/CodeEditor';
import './App.css';

function App() {
    const [language, setLanguage] = useState('javascript'); // Default to JS
    const [code, setCode] = useState('// Write your code here...');
    const [output, setOutput] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    // Function to execute code
    const handleRunCode = async () => {
        setIsLoading(true);

        // 1. Client-Side Execution (HTML/CSS/JS) - WORKS PERFECTLY
        if (language === 'html') {
            setOutput(code);
            setIsLoading(false);
            return;
        }

        // 2. Server-Side Execution (Python, Java, C) - PLACEHOLDER MODE
        // Since we stopped Docker to save RAM, we simulate a response here.
        setTimeout(() => {
            setOutput(`[System Message]: Server-side execution is currently disabled on this machine to save resources.\n\nTo run ${language}, please deploy the backend to a cloud server with Docker support.`);
            setIsLoading(false);
        }, 500); 
    };

    const handleLanguageChange = (e) => {
        const newLang = e.target.value;
        setLanguage(newLang);

        // Set some starter code for each language
        if (newLang === 'html') {
            setCode('<h1>Hello World</h1>\n<p>This runs in your browser!</p>\n<style>\n  h1 { color: #61dafb; }\n  body { font-family: sans-serif; }\n</style>');
        } else if (newLang === 'python') {
            setCode('print("Hello from Python!")');
        } else if (newLang === 'java') {
            setCode('public class Main {\n  public static void main(String[] args) {\n    System.out.println("Hello from Java!");\n  }\n}');
        } else if (newLang === 'c') {
            setCode('#include <stdio.h>\n\nint main() {\n  printf("Hello from C!\\n");\n  return 0;\n}');
        } else {
            setCode('// JavaScript (Node.js mode)');
        }

        // Clear output when switching languages
        setOutput('');
    };

    return (
        <div className="ide-container">
            <header className="header">
                <h2>eLearning IDE</h2>
                <div className="controls">
                    <select value={language} onChange={handleLanguageChange}>
                        <option value="html">HTML/CSS/JS (Web)</option>
                        <option value="javascript">JavaScript (Node)</option>
                        <option value="python">Python</option>
                        <option value="java">Java</option>
                        <option value="c">C</option>
                    </select>
                    <button onClick={handleRunCode} disabled={isLoading}>
                        {isLoading ? 'Running...' : 'Run Code'}
                    </button>
                </div>
            </header>

            <div className="main-content">
                <CodeEditor 
                    language={language === 'html' ? 'html' : language} 
                    code={code} 
                    setCode={setCode} 
                />

                <div className="output-section">
                    <h3>Output</h3>
                    <div className="output-box">
                        {/* If HTML is selected, render an iframe. Otherwise, render text. */}
                        {language === 'html' ? (
                            <iframe 
                                srcDoc={output} 
                                title="output"
                                sandbox="allow-scripts"
                                style={{ width: '100%', height: '100%', border: 'none', backgroundColor: '#fff' }}
                            />
                        ) : (
                            <pre style={{ margin: 0, color: language === 'html' ? 'black' : '#ddd' }}>
                                {output || "Click 'Run Code' to see the output here."}
                            </pre>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default App;
